def transform(grid):
    h, w = len(grid), len(grid[0])

    def line_positions(color):
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.55 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.55 * h]
        return rows, cols

    def periodic_score(indices):
        if len(indices) < 3:
            return 0.0
        gaps = [b - a for a, b in zip(indices, indices[1:])]
        counts = {d: gaps.count(d) for d in set(gaps)}
        gap, count = max(counts.items(), key=lambda x: x[1])
        if gap < 2:
            return 0.0
        return gap * count / len(gaps)

    # Grid separators form regularly spaced, mostly single-color rows and columns.
    sep = None
    best = -1
    for color in range(10):
        rows, cols = line_positions(color)
        score = periodic_score(rows) + periodic_score(cols)
        if score > best:
            best, sep = score, color

    rows, cols = line_positions(sep)
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]

    # The fill color is the most common color away from the separator lines.
    counts = [0] * 10
    for r in range(h):
        if r in rows:
            continue
        for c in range(w):
            if c not in cols and grid[r][c] != sep:
                counts[grid[r][c]] += 1
    base = max(range(10), key=lambda color: counts[color])

    out = [[base for _ in range(len(cols) - 1)] for _ in range(len(rows) - 1)]
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]
            ]
            if corners[0] != sep and corners[0] != base and all(x == corners[0] for x in corners):
                out[i][j] = corners[0]

    # Remove only blank outer margins.
    while out and all(v == base for v in out[0]):
        out.pop(0)
    while out and all(v == base for v in out[-1]):
        out.pop()
    if out:
        while all(row[0] == base for row in out):
            for row in out:
                row.pop(0)
        while all(row[-1] == base for row in out):
            for row in out:
                row.pop()
    return out
